"""Transparent advisory engine. Never equates past failures with increased next-roll luck.

Only comparable observations (same item & rune) enter empirical rates; incomplete
context means these are descriptive frequencies, not causal probabilities.
"""
from dataclasses import dataclass
from math import sqrt
@dataclass(frozen=True)
class Advice:
    rune: str | None
    headline: str
    details: str
    confidence: str
    rates: dict | None = None
    sample: int = 0


def wilson_interval(count, total, z=1.96):
    if total == 0:return (0., 1.)
    p=count/total
    d=1+z*z/total
    c=(p+z*z/(2*total))/d
    r=(z/d)*sqrt(p*(1-p)/total+z*z/(4*total*total))
    return (max(0.,c-r),min(1.,c+r))


def describe_observed(counts):
    n=sum(counts.get(k,0) for k in ('SC','SN','EC'))
    if not n: return None,0
    return ({k:{'rate':counts.get(k,0)/n,'ci95':wilson_interval(counts.get(k,0),n)}
             for k in ('SC','SN','EC')},n)


def recommend(plan, puits=None, jets_confirmed=False, records=None, last_rune=None, last_results=()):
    if not plan or not plan.get('stats'):
        return Advice(None,'Définir un objectif','Choisis les caractéristiques que tu souhaites atteindre.','bloqué')
    if not jets_confirmed:
        return Advice(None,'Jet à actualiser','Forgely doit relire et confirmer le jet après la dernière fusion. Aucun conseil sur un jet périmé.','bloqué')
    if puits is None:
        return Advice(None,'Puits à confirmer','Le reliquat n’est pas encore lu avec suffisamment de fiabilité. Recommandation suspendue.','bloqué')
    from forgely_decision import advise
    def counts_for(rune):
        return records(rune)[1] if records else {'SC':0,'SN':0,'EC':0}
    if any(v.get('current') is None or v.get('target') is None for v in plan['stats'].values()):
        return Advice(None,'Jet incomplet','Valeur actuelle ou objectif inconnu.','bloqué')
    proposal=advise({s:v['current'] for s,v in plan['stats'].items()},
                    {s:v['target'] for s,v in plan['stats'].items()},
                    pool=puits,counts_for=counts_for,item=plan.get('item'),level=plan.get('level'))
    details=proposal.explanation
    if last_rune:details+=f' Dernière rune détectée : {last_rune}.'
    if last_results:details+=' Les échecs passés ne garantissent pas le succès suivant.'
    rates,_=describe_observed(records(proposal.rune)[1]) if records and proposal.rune else (None,0)
    return Advice(proposal.rune,proposal.summary,details,proposal.evidence,rates,proposal.sample)

"""Explainable FM objectives; heuristic scores are NEVER success probabilities."""
from __future__ import annotations
from dataclasses import dataclass
from typing import Mapping
from forgely_probabilites import empirical
from forgely_predictive import estimate, calibrate
from forgely_dofocus import (reference, lookup, lookup_context, natural_profile, line_limit,
    normalise_jet, displayed_number, risk_notes)
from forgely_rules import (RUNE_CHOICES, WEIGHTS as WEIGHT_PER_POINT, CAP,
                          constraints, finite_number, objective_mode, known_prices)


@dataclass(frozen=True)
class Proposal:
    rune: str | None
    kind: str
    summary: str
    explanation: str
    evidence: str
    estimates: dict | None = None
    sample: int = 0


def pool_transition(pool, attempted_weight, lost_weight, outcome):
    if outcome not in ('SC', 'SN', 'EC'):
        raise ValueError('Résultat inconnu')
    if any(not finite_number(v, nonnegative=True) for v in (pool, attempted_weight, lost_weight)):
        raise ValueError('Poids finis non négatifs requis')
    if outcome == 'SC':
        if lost_weight:
            raise ValueError('SC contradictoire avec une perte de caractéristique')
        return float(pool)
    return round(max(0., pool + lost_weight - attempted_weight), 4)


def classify(stat, current, proposed, natural_max: Mapping[str, float] | None, *, profile_complete=True):
    if natural_max is None:
        return 'inconnu'
    if stat not in natural_max:
        return ('exo' if proposed > 0 else 'absent') if profile_complete else 'inconnu'
    return 'over' if proposed > natural_max[stat] else 'fm_classique'


def extra_mass(jets, natural_max):
    """Descriptive surplus only, NOT a shared over/exo legality budget."""
    if natural_max is None:
        return None
    total = 0.
    for stat, amount in jets.items():
        if stat not in WEIGHT_PER_POINT:
            return None
        total += max(0., amount - natural_max.get(stat, 0)) * WEIGHT_PER_POINT[stat]
    return round(total, 5)


def candidates(jets, targets, natural_max=None, pool=None, counts_for=None, *,
               mode='Chances maximales', prices=None, remaining_budget=None, profile_complete=True,item=None, level=None, context_for=None):
    mode = objective_mode(mode)
    if (not targets or not jets or pool is None or not finite_number(pool, nonnegative=True)
            or any(stat not in jets for stat in targets)
            or any(not finite_number(v) for v in (*jets.values(), *targets.values()))
            or (natural_max is not None and any(not finite_number(v) for v in natural_max.values()))
            or (remaining_budget is not None and not finite_number(remaining_budget, nonnegative=True))):
        return []
    prices = known_prices(prices)
    pending_natural = any(current < targets.get(stat, current) and current < natural_max[stat]
                          for stat, current in jets.items() if natural_max and stat in natural_max)
    source_context=lookup_context(item,jets,pool) if item else None
    available = []
    for stat, goal in targets.items():
        current = jets[stat]
        if current >= goal:
            continue
        # Malus handling needs verified signed bounds, rather than positive-line rules.
        if current < 0 or (natural_max and natural_max.get(stat, 0) < 0):
            continue
        for rune in RUNE_CHOICES.get(stat, ()):
            ref = reference(rune)
            if ref.weight is None or ref.gain is None:
                continue
            proposed = current + ref.gain
            # Targets are minima: allow a tiny surplus only inside known natural bounds.
            if proposed > goal and not (natural_max is not None and stat in natural_max
                                         and proposed <= natural_max[stat]):
                continue
            modified = dict(jets)
            modified[stat] = proposed
            checked = constraints(modified, natural_max, complete_profile=profile_complete)
            if checked['valid'] is False:
                continue
            limit=line_limit(item,stat) if item else None
            if limit is not None and proposed>limit:continue
            sampled=source_context.get(rune) if source_context else None
            if sampled and sampled['blocked']:continue
            price = prices.get(rune)
            if not finite_number(price, nonnegative=True):
                price = None
            if (mode == 'Budget optimisé' or remaining_budget is not None) and price is None:
                continue
            if remaining_budget is not None and price > remaining_budget:
                continue
            kind = classify(stat, current, proposed, natural_max, profile_complete=profile_complete)
            counts = counts_for(rune) if counts_for else None
            obs = empirical(counts) if counts is not None else None
            base={'SC':None,'SN':None,'EC':None,'kind':'dofocus_non_documente',
                  'note':'Aucun taux fixe extrapolé depuis une autre source.'}
            prediction = estimate(jets,natural_max,rune,level=level,profile_complete=profile_complete)
            prediction = calibrate(prediction,context_for(rune) if context_for and prediction else None)
            base['prediction'] = prediction
            remaining = goal - current
            progress = min(1., ref.gain / remaining)
            # Approximate exposure, not expected losses: actual loss distribution is unknown.
            exposed = max(0., ref.weight - pool)
            exposure = exposed / max(ref.weight, 1.)
            overshoot = max(0., proposed - goal) / max(1., ref.gain if prediction else remaining)
            # Community tier heuristic: soft penalty, never an impossibility threshold.
            tier_pressure = 0. if prediction else min(4., max(0., current / (20 * ref.gain) - 1.))
            finish_penalty = .8 if pending_natural and kind in ('exo', 'over') else 0.
            balance = 0.
            if natural_max and stat in natural_max and natural_max[stat] > 0:
                balance = .15 * max(0., 1 - current / natural_max[stat])
            non_sc = (100-prediction['SC'])/100 if prediction else 1.
            utility = (progress + balance) / (1 + .7 * exposure * non_sc + .5 * tier_pressure + overshoot)
            utility /= 1 + finish_penalty
            if prediction:
                # Predicted progress, with repair exposure weighted by non-SC mass.
                utility *= (prediction['SC']+prediction['SN'])/100
            elif sampled and not sampled['blocked']:
                display=sampled['display']
                utility *= (displayed_number(display['SC'])+displayed_number(display['SN']))/100
            if mode == 'Budget optimisé':
                # Price plus repair exposure valued at known cheapest cost per density.
                repair_prices = [p / reference(r).weight for r, p in prices.items()
                                 if finite_number(p, nonnegative=True) and reference(r).weight]
                repair_proxy = exposed * min(repair_prices) if repair_prices else 0.
                if prediction: repair_proxy *= (100-prediction['SC'])/100
                score = utility / max(1., price + repair_proxy)
            else:
                score = utility - .04 * ref.weight / 100 - finish_penalty
            available.append((score, rune, stat, kind, ref, base, obs,
                              extra_mass(modified, natural_max), current, goal))
    # Restore an available targeted natural line before risking a final over/exo.
    # This priority is independent of the rune prices, unlike the soft score.
    if pending_natural and any(row[3] == 'fm_classique' for row in available):
        available = [row for row in available if row[3] not in ('exo', 'over')]
    return sorted(available, key=lambda x: (-x[0], x[1]))


def advise(jets, targets, natural_max=None, pool=None, counts_for=None, after_fusion=False, *,
           mode='Chances maximales', prices=None, remaining_budget=None, profile_complete=True,item=None, level=None, context_for=None):
    jets=normalise_jet(jets)
    targets=normalise_jet(targets)
    if jets is None or targets is None:
        return Proposal(None,'bloqué','Valeurs invalides','Jet ou cible invalide.','Dofocus · contrôle des lectures')
    documented=natural_profile(item) if item else None
    if documented is not None:
        natural_max=documented
        profile_complete=True
    elif natural_max is not None:
        natural_max=normalise_jet(natural_max)
        if natural_max is None:
            return Proposal(None,'bloqué','Bornes naturelles invalides',
                            'Le profil fourni ne permet pas de vérifier les contraintes.','Dofocus · contrôle des bornes')
    mode = objective_mode(mode)
    prices = known_prices(prices)
    def blocked(title, detail):
        return Proposal(None, 'bloqué', title, detail, 'aucune')
    if after_fusion:
        return blocked('Jet à relire', 'Attendre une lecture stable du nouveau jet après la fusion.')
    if not targets:
        return blocked('Aucun objectif', 'Définis le jet cible de cet équipement.')
    if pool is None:
        return blocked('Reliquat à confirmer', 'Aucune recommandation tant que le reliquat n’est pas confirmé.')
    if (not finite_number(pool, nonnegative=True)
            or any(not finite_number(v) for v in (*jets.values(), *targets.values()))):
        return blocked('Valeurs invalides', 'Le jet et le reliquat doivent être des nombres finis confirmés.')
    if any(s not in jets for s in targets):
        return blocked('Jet incomplet', 'Toutes les lignes ciblées doivent être lues et confirmées.')
    if all(jets[s] >= v for s, v in targets.items()):
        return Proposal(None, 'atteint', 'Objectif atteint',
                        'Ne pose pas de rune supplémentaire sans nouvel objectif.', 'état confirmé')
    if remaining_budget is not None and not finite_number(remaining_budget, nonnegative=True):
        return blocked('Budget invalide', 'Renseigne un budget restant fini et positif ou nul.')
    if remaining_budget == 0:
        return blocked('Budget épuisé', 'Arrêt conseillé : aucune dépense supplémentaire autorisée par le budget.')
    options = candidates(jets, targets, natural_max, pool, counts_for, mode=mode, prices=prices,
                         remaining_budget=remaining_budget, profile_complete=profile_complete,item=item,level=level,context_for=context_for)
    if not options:
        return blocked('Aucune rune à proposer',
                       'Vérifie les prix, le budget restant, les bornes naturelles, les malus et les plafonds de lignes.')
    score, rune, stat, kind, ref, base, obs, weight, current, goal = options[0]
    sampled=lookup(item,jets,pool,rune) if item else None
    exposure = max(0., ref.weight - pool)
    explanation = (f'{mode} · {stat} : {current:g} → minimum {goal:g}. '
                   f'{rune} : gain nominal +{ref.gain:g}, poids {ref.weight:g}, reliquat {pool:g}. '
                   f'Poids non couvert par le reliquat : {exposure:g} (exposition, pas perte prédite). '
                   f'Type : {kind}. ')
    if natural_max is None or not profile_complete:
        explanation += 'Profil naturel incomplet : absence de ligne et légalité globale non certifiées. '
    if kind in ('exo', 'over'):
        explanation += 'Finition fragile : les poses suivantes peuvent dégrader cet ajout. '
    price = (prices or {}).get(rune)
    explanation += f'Prix unitaire de référence : {price:g} kamas. ' if price is not None else 'Prix inconnu. '
    if remaining_budget is not None:
        explanation += f'Budget restant avant pose : {remaining_budget:g} kamas. '
    if mode == 'Budget optimisé':
        explanation += 'Classement par progression/prix et exposition de réparation approximative ; coût final inconnu. '
    else:
        explanation += 'Classement par progression, palier de rune, équilibre des lignes et protection du jet. '
    prediction=base.get('prediction')
    if prediction:
        explanation += (f"Modèle vidéo estimé : SC {prediction['SC']:.2f} %, SN {prediction['SN']:.2f} %, EC {prediction['EC']:.2f} %. "
                        f"Calibration : {prediction['calibration_n']} résultats réels comparables ; poids réel {100*prediction['real_weight']:.1f} %. "
                        + '; '.join(prediction['assumptions']) + '. ')
    n = obs['n'] if obs else 0
    if n:
        explanation += f'{n} observations agrégées : descriptives, non utilisées comme probabilités du prochain essai. '
    if sampled and not sampled['blocked']:
        display=sampled['display']
        explanation+=(f"Simulation Dofocus relevée le {sampled['captured_on']}, même jet complet et même reliquat : "
                      f"SC {display['SC']} %, SN {display['SN']} %, EC {display['EC']} %. "
                      "Valeurs affichées arrondies, non validées comme probabilités du jeu. ")
    else:
        explanation+=('Aucun relevé Dofocus pour ce contexte exact. ' if prediction else 'Aucun relevé Dofocus pour ce contexte exact : pourcentages non disponibles. ')
    for note in risk_notes(current,current+ref.gain,ref.weight,pool,
                          natural_max.get(stat,0) if natural_max is not None and profile_complete else None):
        explanation+=note+' '
    explanation+='Politique Forgely : gardes conservatrices de plafond par ligne et d’exos cumulés à 101 ; pas une formule Dofocus publiée. '
    explanation+='Choix de rune indicatif selon l’objectif, sans garantie de réussite.'
    alternatives = [{'rune': row[1], 'stat': row[2], 'score': round(row[0], 6),
                     'price': (prices or {}).get(row[1]), 'prediction':row[5].get('prediction')} for row in options[:5]]
    return Proposal(rune, kind, f'À envisager : {rune}', explanation, 'Modèle vidéo estimé · Densités du client · relevés Dofocus séparés ; classement Forgely',
                    {'observed': obs, 'benchmark': base,'dofocus':sampled,'prediction':prediction,
                     'objective': {'mode': mode, 'remaining_budget': remaining_budget,
                                   'exposed_weight': exposure, 'alternatives': alternatives,
                                   'goal_probability': None}}, n)

"""Client-derived weights and conservative Forgely constraints, checked 2026-11-08.

Not the proprietary success algorithm. A partial profile never proves absence.
Weights: versioned client extraction in forgely_weights; not publisher verified.
Simulator display contexts: https://dofocus.fr/forgemagie/
The retained 101 line/exotic guards are Forgely policy, not a reconstructed
Dofocus formula. Historical background remains in docs/FM_DOUBLE_OBJECTIF.md.
"""
from math import isfinite
from forgely_dofocus import (reference, RUNE_CHOICES as DOFOCUS_CHOICES,
                             WEIGHT_PER_POINT, canonical_stat)

MODES = ('Chances maximales', 'Budget optimisé')
RUNE_CHOICES = {stat:tuple(runes) for stat,runes in DOFOCUS_CHOICES.items()}
# Keep spellings accepted by earlier objective files.
for alias in ('Coups critiques','Invocation','Dommages critiques','Dommages poussée'):
    RUNE_CHOICES[alias]=RUNE_CHOICES[canonical_stat(alias)]
WEIGHTS = {stat:WEIGHT_PER_POINT[canonical_stat(stat)] for stat in RUNE_CHOICES}

CAP = 101.0


def finite_number(value, *, nonnegative=False):
    return (isinstance(value, (int, float)) and not isinstance(value, bool)
            and isfinite(value) and (not nonnegative or value >= 0))


def known_prices(prices):
    """Missing/invalid is unknown, never a free rune or a displayable price."""
    return {r:p for r,p in (prices or {}).items() if finite_number(p,nonnegative=True)}


def constraints(jets, natural_max, *, complete_profile=True, cap=CAP):
    """Tri-state constraint check, not a guarantee that a rune will pass.

    Over: total resulting line density <=101. Natural high lines stay legal.
    Exotics: cumulative density <=101. Unknown weights/profile => unknown.
    Negative natural lines require separate malus rules; no silent approval.
    """
    if not finite_number(cap, nonnegative=True):
        return {'valid': False, 'reason': 'Plafond invalide', 'exotic_weight': None}
    if any(not finite_number(v) for v in jets.values()):
        return {'valid': False, 'reason': 'Jet invalide', 'exotic_weight': None}
    if natural_max is None:
        return {'valid': None, 'reason': 'Profil naturel inconnu', 'exotic_weight': None}
    if any(not finite_number(v) for v in natural_max.values()):
        return {'valid': False, 'reason': 'Bornes naturelles invalides', 'exotic_weight': None}
    exotic = 0.0
    unknown = False
    for stat, value in jets.items():
        maximum = natural_max.get(stat)
        weight = WEIGHTS.get(stat)
        if value < 0 or (maximum is not None and maximum < 0):
            unknown = True
            continue
        if maximum is not None:
            if value <= maximum:
                continue
            if weight is None:
                unknown = True
            elif value * weight > cap + 1e-8:
                return {'valid': False, 'reason': f'Plafond de ligne over dépassé : {stat}', 'exotic_weight': exotic}
        elif value:
            if not complete_profile or weight is None:
                unknown = True
            else:
                exotic += value * weight
    if exotic > cap + 1e-8:
        return {'valid': False, 'reason': 'Densité cumulée des exos dépassée', 'exotic_weight': exotic}
    return {'valid': None if unknown else True,
            'reason': 'Contraintes non vérifiables sur toutes les lignes' if unknown else 'Sous les gardes conservatrices Forgely (pas une formule Dofocus publiée)',
            'exotic_weight': round(exotic, 4)}


def objective_mode(value):
    """Retain legacy settings; old economy preference maps to the new mode."""
    if value in ('Économique', 'Budget optimisé'):
        return MODES[1]
    if value in (*MODES, 'Prudent', 'Rapide', 'Jet parfait'):
        return MODES[0]
    raise ValueError('Mode de recommandation inconnu')

"""Versioned rune densities from a third-party extraction of the game client.

This is not an Ankama-published table or a source of success probabilities.
No networking or training occurs here. Both advisor entrypoints use this table.
"""
from functools import lru_cache
import json
from math import isfinite
from pathlib import Path

PATH = Path(__file__).parent / 'references' / 'poids_runes_client_3_7_13_17.json'


@lru_cache(maxsize=1)
def _load():
    data = json.loads(PATH.read_text(encoding='utf8'))
    if data.get('schema') != 1 or len(data.get('runes', [])) != 105:
        raise ValueError('Catalogue de densités incomplet')
    seen = set()
    for row in data['runes']:
        if row['rune'] in seen:
            raise ValueError('Rune en doublon')
        seen.add(row['rune'])
        if row['kind'] == 'signature_non_combat':
            if any(row[k] is not None for k in ('gain', 'weight', 'unit_weight')):
                raise ValueError('Signature sans densité de combat')
            continue
        if any(type(row[k]) not in (int, float) or not isfinite(row[k]) or row[k] <= 0
               for k in ('gain', 'weight', 'unit_weight')):
            raise ValueError('Densité invalide')
        if abs(row['gain'] * row['unit_weight'] - row['weight']) > 1e-6:
            raise ValueError('Gain et densité incohérents')
    return data


def load_weights():
    # Callers must not be able to mutate the active catalogue through this API.
    from copy import deepcopy
    return deepcopy(_load())

"""Versioned Dofocus reference; simulator displays are never real game trials.

No network calls, no game actions and no writes to the observation database.
Only full, equal starting states may reuse a recorded percentage display.
"""
from __future__ import annotations
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path
from math import isfinite
import json
import unicodedata
from datetime import date

SOURCE_URL = 'https://dofocus.fr/forgemagie/'
GUIDE_URL = 'https://dofocus.fr/guide/'
REFERENCE_PATH = Path(__file__).with_name('references') / 'dofocus' / 'reference.json'
STORE_PATH = Path(__file__).with_name('assets') / 'dofocus' / 'reference.sqlite3'


def key(text):
    return ' '.join(''.join(c for c in unicodedata.normalize('NFKD',str(text)).casefold()
                            if not unicodedata.combining(c)).split())


# Densities come from the versioned client extraction, not simulator percentages.
# Ordinary stats and tiers are built from actual rune gains, never assumed.
from forgely_weights import load_weights
_WEIGHT_DATA = load_weights()
_GROUPS = {}
for _row in _WEIGHT_DATA['runes']:
    if _row['kind'] == 'ordinaire':
        _GROUPS.setdefault(_row['stat'], []).append(_row)
FAMILIES = {}
for _stat, _rows in _GROUPS.items():
    _rows.sort(key=lambda row: row['gain'])
    _base = _rows[0]
    FAMILIES[_stat] = (_base['rune'], _base['gain'], _base['unit_weight'],
                      tuple(row['gain'] / _base['gain'] for row in _rows))

ALIASES = {key(s):s for s in FAMILIES}
ALIASES.update({key("Points d'action (PA)"):'PA',key('Points de mouvement (PM)'):'PM',
                key('Coups Critiques (%)'):'Coups Critiques',key('Invocation'):'Invocations',
                key('Résistances Critiques (fixe)'):'Résistance Critique',
                key('Résistance Poussée (fixe)'):'Résistance Poussée',
                key('Résistances Poussée (fixe)'):'Résistance Poussée'})
for element in ('Neutre','Terre','Feu','Eau','Air'):
    ALIASES[key(f'Dommages {element} (fixe)')]=f'Dommages {element}'
    for prefix in ('Résistance','Résistances'):
        ALIASES[key(f'{prefix} {element} (fixe)')]=f'Résistance {element}'
        ALIASES[key(f'{prefix} {element}')]=f'Résistance {element}'
        ALIASES[key(f'{prefix} {element} (%)')]=f'% Résistance {element}'
        ALIASES[key(f'% {prefix} {element}')]=f'% Résistance {element}'


def canonical_stat(stat):
    return ALIASES.get(key(stat), str(stat))


def finite_number(value):
    return isinstance(value,(int,float)) and not isinstance(value,bool) and isfinite(value)


def normalise_jet(jets):
    if not isinstance(jets,dict):return None
    result={}
    for stat,value in jets.items():
        if not finite_number(value):return None
        name=canonical_stat(stat)
        if name in result:return None  # duplicate aliases make completeness ambiguous
        result[name]=value
    return result


@dataclass(frozen=True)
class RuneReference:
    name: str
    gain: float | None
    weight: float | None


RUNE_CHOICES = {stat: [row['rune'] for row in rows] for stat, rows in _GROUPS.items()}
RUNE_REFERENCES = {row['rune']: RuneReference(row['rune'], row['gain'], row['weight'])
                   for row in _WEIGHT_DATA['runes']}
WEIGHT_PER_POINT = {stat: rows[0]['unit_weight'] for stat, rows in _GROUPS.items()}


def reference(rune):
    return RUNE_REFERENCES.get(rune,RuneReference(rune,None,None))


def displayed_number(text):
    if not isinstance(text,str):raise ValueError('Pourcentage affiché invalide')
    value=float(text.removeprefix('≈').replace(',','.'))
    if not isfinite(value) or not 0<=value<=100:raise ValueError('Pourcentage hors limites')
    return value


def validate_catalogue(data):
    try:
        return _validate_catalogue(data)
    except (AttributeError,KeyError,TypeError,IndexError) as error:
        raise ValueError('Structure du référentiel invalide') from error


def _validate_catalogue(data):
    if not isinstance(data,dict) or data.get('source')!='Dofocus':
        raise ValueError('Provenance Dofocus requise')
    captured=data.get('captured_on')
    if not isinstance(captured,str) or date.fromisoformat(captured).isoformat()!=captured:
        raise ValueError('Date de consultation invalide')
    if not isinstance(data.get('snapshots'),list):raise ValueError('Liste de contextes attendue')
    if data.get('schema')!=1 or data.get('kind')!='simulation_reference' or type(data.get('real_attempts')) is not int or data['real_attempts']!=0:
        raise ValueError('Référence de simulation attendue')
    if not data.get('snapshots'):raise ValueError('Référence vide')
    seen=set()
    for sample in data['snapshots']:
        if not isinstance(sample,dict) or not isinstance(sample.get('item'),str) or not sample['item'].strip():
            raise ValueError('Objet invalide')
        if not isinstance(sample.get('rows'),list) or not sample['rows']:raise ValueError('Lignes attendues')
        ident=sample['item_id']
        if type(ident) is not int or ident<=0 or sample['url']!=SOURCE_URL+str(ident):
            raise ValueError('URL de provenance invalide')
        if not finite_number(sample['pool']) or sample['pool']<0:raise ValueError('Reliquat invalide')
        jet={}
        for row in sample['rows']:
            if not isinstance(row,dict) or not isinstance(row.get('runes'),dict):raise ValueError('Ligne invalide')
            name=canonical_stat(row['stat'])
            if name not in RUNE_CHOICES:raise ValueError('Caractéristique inconnue')
            if name in jet or not finite_number(row['value']):raise ValueError('Jet ambigu')
            jet[name]=row['value']
            lo,hi=row['min'],row['max']
            if (lo is None)!=(hi is None):raise ValueError('Bornes incomplètes')
            if lo is not None and (not finite_number(lo) or not finite_number(hi) or lo>hi):
                raise ValueError('Bornes invalides')
            for rune,result in row['runes'].items():
                if rune not in RUNE_CHOICES[name]:raise ValueError('Rune attribuée à une autre caractéristique')
                if not isinstance(result,dict) or type(result.get('blocked')) is not bool:raise ValueError('Résultat invalide')
                if result['blocked']:
                    if not finite_number(result['line_max']):raise ValueError('Plafond invalide')
                    continue
                if set(result['display'])!={'SC','SN','EC'}:raise ValueError('Résultats incomplets')
                values=[displayed_number(result['display'][k]) for k in ('SC','SN','EC')]
                # Displayed, independently rounded percentages need not sum to exactly 100.
                if abs(sum(values)-100)>1.5:raise ValueError('Pourcentages incohérents')
                ref=reference(rune)
                if ref.weight is None or not finite_number(result['weight']) or abs(ref.weight-result['weight'])>1e-6:
                    raise ValueError('Poids incohérent : '+rune)
        signature=(key(sample['item']),tuple(sorted(jet.items())),sample['pool'])
        if signature in seen:raise ValueError('Contexte dupliqué')
        seen.add(signature)
    return data


@lru_cache(maxsize=1)
def catalogue():
    try:
        return validate_catalogue(json.loads(REFERENCE_PATH.read_text(encoding='utf-8')))
    except (OSError,ValueError,KeyError,TypeError):
        # Missing/broken reference disables exact displays, never invents rates.
        return {'schema':1,'kind':'simulation_reference','real_attempts':0,'snapshots':[]}


@lru_cache(maxsize=1)
def _cached_store(path,stamp,size):
    from forgely_dofocus_store import ReferenceStore
    return ReferenceStore(path)


def reference_store():
    try:
        info=STORE_PATH.stat()
        stamp,size=info.st_mtime_ns,info.st_size
    except OSError:
        stamp,size=None,None
    return _cached_store(str(STORE_PATH),stamp,size)


def natural_profile(item):
    return reference_store().profile(item)


def lookup_context(item,jets,pool):
    return reference_store().context(item,jets,pool)


def lookup(item,jets,pool,rune):
    return reference_store().rune(item,jets,pool,rune)


def line_limit(item,stat):
    return reference_store().limit(item,stat)


def risk_notes(current, proposed, weight, pool, natural_max=None):
    notes=['Référence : Dofocus — '+SOURCE_URL]
    if current<0:
        notes.append('Ligne en malus : le simulateur affiche un coût réduit de moitié ; le franchissement de zéro nécessite un relevé spécifique.')
    if natural_max is None:
        notes.append('Bornes naturelles inconnues : type de tentative non vérifiable.')
    elif proposed>natural_max:
        notes.append('Le gain proposé dépasse le maximum naturel : vérifier le risque d’over ou d’exo dans le simulateur.')
    if pool<weight:
        notes.append('Reliquat inférieur au poids nominal : les autres lignes peuvent être exposées à une perte.')
    else:
        notes.append('Reliquat au moins égal au poids nominal ; cela ne garantit pas le passage.')
    return notes
